INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cf25', 'Olive Oil', 120, 'ml', 7);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf25', 1, 'Saute the onions in the 3-4 tablespoons olive oil');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf25', 2, 'Add the beef cubes or the chicken cutlets, sear for 3-4 min on each side');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf25', 3, 'Add 1 liter of water or just enough to cover the meat');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf25', 4, 'Cook over medium heat until the meat is done (I usually do this in the pressure cooker and press them for 5 min)');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf25', 5, 'Add the frozen mulukhyia and stir until it thaws completely and then comes to a boil');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf25', 6, 'In another pan add the 1/4 to 1/2 cup of olive oil and the cloves of garlic and cook over medium low heat until you can smell the garlic (don’t brown it, it will become bitter)');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf25', 7, 'Add the oil and garlic to the mulukhyia and lower the heat and simmer for 5-10 minutes');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf25', 8, 'Add salt to taste');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf25', 9, 'Serve with a generous amount of lemon juice.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf25', 10, 'You can serve it with some short grain rice or some pita bread');
INSERT INTO recipes (id, name, description, meal_type, servings) VALUES ('00000000-0000-4000-8000-00000000cecf', 'Oxtail with broad beans', 'Danie: Jamaican. Źródło: TheMealDB', 'lunch', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000cecf', 'Oxtail', 450, 'g', 1);
