INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced6', 1, 'STEP 1 - MARINATING THE BEEF');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced6', 2, 'In a bowl, add the beef, salt, sesame seed oil, white pepper, egg white, 2 Tablespoon of corn starch and 1 Tablespoon of oil.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced6', 3, 'STEP 2 - STIR FRY');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced6', 4, 'First Cook the beef by adding 2 Tablespoon of oil until the beef is golden brown.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced6', 5, 'Set the beef aside');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced6', 6, 'In a wok add 1 Tablespoon of oil, minced ginger, minced garlic and stir-fry for few seconds.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced6', 7, 'Next add all of the vegetables and then add sherry cooking wine and 1 cup of water.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced6', 8, 'To make the sauce add oyster sauce, hot pepper sauce, and sugar.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced6', 9, 'add the cooked beef and 1 spoon of soy sauce');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced6', 10, 'To thicken the sauce, whisk together 1 Tablespoon of cornstarch and 2 Tablespoon of water in a bowl and slowly add to your stir-fry until it''s the right thickness.');
INSERT INTO recipes (id, name, description, meal_type, servings) VALUES ('00000000-0000-4000-8000-00000000cfcf', 'Thai beef stir-fry', 'Danie: Thai. Źródło: TheMealDB', 'lunch', 4) ON CONFLICT (id) DO NOTHING;
